(()=>{const q=document.getElementById('query'),s=document.getElementById('state'),c=document.getElementById('category');if(!q)return;const cards=[...document.querySelectorAll('.vendor-card')];function filter(){let n=0;for(const card of cards){const show=card.dataset.search.includes(q.value.toLowerCase().trim())&&(!s.value||card.dataset.state===s.value)&&(!c.value||card.dataset.category===c.value);card.classList.toggle('hidden',!show);if(show)n++}document.getElementById('result-count').textContent=n+' vendor profile'+(n===1?'':'s');document.getElementById('no-results').classList.toggle('hidden',n!==0)}for(const x of [q,s,c])x.addEventListener('input',filter);filter()})();